def satisfies(version: str, spec: str) -> bool:
    def parse_version(v: str):
        if not isinstance(v, str):
            raise ValueError("malformed version")
        parts = v.split('.')
        if len(parts) != 3:
            raise ValueError("malformed version")
        nums = []
        for p in parts:
            if not p or any(ch not in '0123456789' for ch in p):
                raise ValueError("malformed version")
            if len(p) > 1 and p[0] == '0':
                raise ValueError("malformed version")
            nums.append(int(p))
        return tuple(nums)

    def parse_comparator(token: str):
        for op in ('>=', '<=', '>', '<', '='):
            if token.startswith(op):
                base = parse_version(token[len(op):])
                return op, base
        raise ValueError("malformed spec")

    def cmp_op(v, op, base):
        if op == '>=':
            return v >= base
        if op == '>':
            return v > base
        if op == '<=':
            return v <= base
        if op == '<':
            return v < base
        if op == '=':
            return v == base
        raise ValueError("malformed spec")

    ver = parse_version(version)
    spec = spec.strip()
    if not spec:
        raise ValueError("malformed spec")

    # caret or tilde range
    if spec[0] in '^~':
        if ' ' in spec:
            raise ValueError("malformed spec")
        base = parse_version(spec[1:])
        if spec[0] == '^':
            if base[0] > 0:
                upper = (base[0] + 1, 0, 0)
            elif base[1] > 0:
                upper = (0, base[1] + 1, 0)
            else:
                return ver == base
            return base <= ver < upper
        else:  # tilde
            upper = (base[0], base[1] + 1, 0)
            return base <= ver < upper

    # space-separated conjunction of comparators
    if ' ' in spec:
        tokens = spec.split()
        for token in tokens:
            op, base = parse_comparator(token)
            if not cmp_op(ver, op, base):
                return False
        return True

    # single comparator or exact version
    for op in ('>=', '<=', '>', '<', '='):
        if spec.startswith(op):
            base = parse_version(spec[len(op):])
            return cmp_op(ver, op, base)

    # exact version
    base = parse_version(spec)
    return ver == base
